import { test, expect } from '@playwright/test';

test.describe('Date Picker Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/booking'); // Replace with the actual URL of the booking page
  });

  test('should not allow selecting past dates', async ({ page }) => {
    const today = new Date();
    const pastDate = new Date(today);
    pastDate.setDate(today.getDate() - 1);
    const formattedPastDate = pastDate.toISOString().split('T')[0];

    await page.getByLabel('Select Date').fill(formattedPastDate);
    const errorMessage = await page.getByText('Please select a valid date.').isVisible();

    expect(errorMessage).toBeTruthy();
  });

  test('should allow selecting today or future dates', async ({ page }) => {
    const today = new Date();
    const formattedToday = today.toISOString().split('T')[0];

    await page.getByLabel('Select Date').fill(formattedToday);
    const errorMessage = await page.getByText('Please select a valid date.').isVisible();

    expect(errorMessage).toBeFalsy();

    const futureDate = new Date(today);
    futureDate.setDate(today.getDate() + 1);
    const formattedFutureDate = futureDate.toISOString().split('T')[0];

    await page.getByLabel('Select Date').fill(formattedFutureDate);
    const futureErrorMessage = await page.getByText('Please select a valid date.').isVisible();

    expect(futureErrorMessage).toBeFalsy();
  });
});
